function sanitizeDbKey(key) {
  return String(key).replace(/[.#$[\]/]/g, "_");
}
window.storage = {
  async get(key, shared) {
    if (!shared) {
      const value = window.localStorage.getItem(key);
      if (value === null) throw new Error("key not found: " + key);
      return { key, value, shared };
    }
    await authReady;
    const snap = await dbGet(ref(fbDb, sanitizeDbKey(key)));
    if (!snap.exists()) throw new Error("key not found: " + key);
    return { key, value: snap.val(), shared };
  },
  async set(key, value, shared) {
    if (!shared) {
      window.localStorage.setItem(key, value);
      return { key, value, shared };
    }
    await authReady;
    await dbSet(ref(fbDb, sanitizeDbKey(key)), value);
    return { key, value, shared };
  },
  async delete(key, shared) {
    if (!shared) {
      window.localStorage.removeItem(key);
      return { key, deleted: true, shared };
    }
    await authReady;
    await dbRemove(ref(fbDb, sanitizeDbKey(key)));
    return { key, deleted: true, shared };
  },
  list() {
    return Promise.resolve({ keys: [] });
  }
};
